mapper.insert:
insert into biz_member (
    phone, password, pay_password, invite_code, parent_id, ancestors, real_name, id_card,
    kyc_status, level_id, status, withdraw_status, create_by, create_time, remark
) values (
    #{phone}, #{password}, #{payPassword}, #{inviteCode}, #{parentId}, #{ancestors}, #{realName}, #{idCard},
    #{kycStatus}, #{levelId,jdbcType=BIGINT}, #{status}, #{withdrawStatus}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update biz_member
phone = #{phone}, password = #{password}, pay_password = #{payPassword}, invite_code = #{inviteCode}, parent_id = #{parentId}, ancestors = #{ancestors}, real_name = #{realName}, id_card = #{idCard}, kyc_status = #{kycStatus}, level_id = #{levelId}, status = #{status}, withdraw_status = #{withdrawStatus}, test_flag = #{testFlag}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where member_id = #{memberId}

update biz_member
set ga_secret = #{gaSecret}, ga_status = #{gaStatus}, update_time = sysdate()
where member_id = #{memberId}

update biz_member
set pay_password = #{payPassword}, update_time = sysdate()
where member_id = #{memberId}

mapper.select:
find_in_set(#{memberId}, m.ancestors)
and (length(ifnull(m.ancestors,'')) - length(replace(ifnull(m.ancestors,''), ',', '')) - ifnull(#{viewerDepth}, 0)) = #{teamLevel}
order by m.member_id desc

select m.member_id, m.real_name, m.phone, m.kyc_status, as team_level, ifnull((select sum(r.amount) from biz_recharge r where r.member_id = m.member_id and r.currency = 'USDT' and r.status = '1'), 0) as recharge_usdt, ifnull((select sum(r.amount) from biz_recharge r where r.member_id = m.member_id and r.currency = 'CNY' and r.status = '1'), 0) as recharge_cny, ifnull((select sum(o.price) from biz_order o where o.member_id = m.member_id and o.currency = 'USDT'), 0) as subscribe_usdt, ifnull((select sum(o.price) from biz_order o where o.member_id = m.member_id and o.currency = 'CNY'), 0) as subscribe_cny from biz_member m where find_in_set(#{memberId}, m.ancestors) and ifnull(m.test_flag, '0') = '0' and between 1 and 7
and = #{teamLevel}
order by m.member_id desc

select count(1)
from biz_member
where id_card is not null and id_card != ''
  and upper(id_card) = #{idCard}

    and member_id <> #{excludeMemberId}
